export const GET_LAST_QUARTER_OPTION = (toLocalDateTime = defaultToLocalDateTime, translate = defaultTranslate, toReverseOffsetDateTime = defaultToReverseOffsetDateTime) => {
    const endDate = getNewEndDate(toLocalDateTime);
    const currentQuarter = Math.floor((endDate.getMonth() + 3) / 3);
    const quarterEndMonth = (currentQuarter - 1) * 3;
    const quarterStartMonth = quarterEndMonth - 3;
    const startDate = new Date(endDate);
    startDate.setMonth(quarterStartMonth);
    startDate.setDate(1);
    startDate.setHours(0);
    startDate.setMinutes(0);
    startDate.setSeconds(0);
    endDate.setMonth(quarterEndMonth);
    endDate.setDate(1);
    endDate.setHours(0);
    endDate.setMinutes(0);
    endDate.setMinutes(-1);
    const from = toReverseOffsetDateTime(startDate);
    const to = toReverseOffsetDateTime(endDate);
    return {
        label: translate("Last quarter"),
        getRange: () => ({
            from,
            to
        })
    };
};
export const GET_THIS_QUARTER_OPTION = (toLocalDateTime = defaultToLocalDateTime, translate = defaultTranslate, toReverseOffsetDateTime = defaultToReverseOffsetDateTime) => {
    const startDate = getNewStartDate(toLocalDateTime);
    const currentQuarter = Math.floor((startDate.getMonth() + 3) / 3);
    const quarterStartMonth = (currentQuarter - 1) * 3;
    startDate.setMonth(quarterStartMonth);
    startDate.setDate(1);
    startDate.setHours(0);
    startDate.setMinutes(0);
    const endDate = new Date(startDate);
    endDate.setMonth(quarterStartMonth + 3);
    endDate.setDate(0);
    endDate.setSeconds(59);
    const from = toReverseOffsetDateTime(startDate);
    const to = toReverseOffsetDateTime(new Date(addMinutes(endDate, 23 * 60 + 59)));
    return {
        label: translate("This quarter"),
        getRange: () => ({
            from,
            to
        })
    };
};
export const GET_LAST_YEAR_OPTION = (toLocalDateTime = defaultToLocalDateTime, translate = defaultTranslate, toReverseOffsetDateTime = defaultToReverseOffsetDateTime) => {
    const startDate = getNewStartDate(toLocalDateTime);
    startDate.setFullYear(startDate.getFullYear() - 1);
    startDate.setMonth(0);
    startDate.setDate(1);
    startDate.setHours(0);
    startDate.setMinutes(0);
    const endDate = new Date(startDate);
    endDate.setMonth(11);
    endDate.setDate(31);
    endDate.setSeconds(59);
    const from = toReverseOffsetDateTime(startDate);
    const to = toReverseOffsetDateTime(new Date(addMinutes(endDate, 23 * 60 + 59)));
    return {
        label: translate("Last year"),
        getRange: () => ({
            from,
            to
        })
    };
};
